void webrtc_VideoView_resize(webrtc_VideoView_events events, const webrtc_VideoSize *size) {
	asuka_writer asuka_w = {0};
	w_VideoSize(&asuka_w, &(*size));
	asuka_native_emit(events.view, "Resize", asuka_w.data, asuka_w.len);
	asuka_writer_free(&asuka_w);
}

static void *view_make(const char *name, uint32_t view, void *parent, void **widget, uint32_t *index) {
	if (strcmp(name, "VideoView") == 0) {
		webrtc_VideoView *v = webrtc_make_VideoView((webrtc_VideoView_events){view, parent});
		if (!v) return NULL;
		*widget = v->widget;
		*index = 0;
		return v;
	}
	return NULL;
}

static void view_set(void *obj, uint32_t index, const char *prop, asuka_reader *r) {
	switch (index) {
	case 0: {
		webrtc_VideoView *v = obj;
		if (strcmp(prop, "Track") == 0) {
			webrtc_Track a = r_Track(r);
			if (!r->failed && v->vt->set_track) v->vt->set_track(v, &a);
			webrtc_Track_free(&a);
			return;
		}
		if (strcmp(prop, "Mirror") == 0) {
			bool a = asuka_reader_bool(r);
			if (!r->failed && v->vt->set_mirror) v->vt->set_mirror(v, a);
			return;
		}
		if (strcmp(prop, "Fit") == 0) {
			webrtc_Fit a = asuka_reader_i64(r);
			if (!r->failed && v->vt->set_fit) v->vt->set_fit(v, a);
			return;
		}
		(void)v;
		return;
	}
	}
	(void)prop;
	(void)r;
}

static bool view_measure(void *obj, uint32_t index, float width, float height, float *out_width, float *out_height) {
	switch (index) {
	case 0: {
		webrtc_VideoView *v = obj;
		return v->vt->measure && v->vt->measure(v, width, height, out_width, out_height);
	}
	}
	return false;
}

static void view_destroy(void *obj, uint32_t index) {
	switch (index) {
	case 0: {
		webrtc_VideoView *v = obj;
		if (v->vt->destroy) v->vt->destroy(v);
		else free(v);
		return;
	}
	}
}

static const asuka_native_views views = {view_make, view_set, view_measure, view_destroy};

static const asuka_native_provider provider = {
	.path = "platform/webrtc",
	.make = make,
	.call = call,
	.start = start,
	.release = release,
	.views = &views,
};

ASUKA_NATIVE_CONSTRUCTOR(register_webrtc) { asuka_native_register(&provider); }
